import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';

/**
 * Bearilly login-bridge route — generated by Buildgram.
 *
 * Authenticates against Bearilly shared accounts; connected school Supabase auth is not part of this login flow.
 *
 * POST /api/bearilly-login with JSON { email, password }.
 *
 * The route forwards credentials with the private school API key and stores the short-lived Bearilly session in an HttpOnly cookie.
 * The catch-all proxy at /api/v1/[...path]/route.js reads this cookie on every request.
 *
 * BEARILLY_URL and BEARILLY_API_KEY are read server-side only; they are never sent
 * to the browser.
 */

const BEARILLY_URL = process.env.BEARILLY_URL || '';
const normalizeHostname = (hostname) => hostname.toLowerCase().replace(/^www\./, '');
const BEARILLY_API_KEY = process.env.BEARILLY_API_KEY || '';
const COOKIE_NAME = 'bearilly_session';
const SCHOOL_COOKIE_NAME = 'bearilly_school_id';
const COOKIE_MAX_AGE = 14 * 60; // 14 minutes — safely within the 15-min token lifetime

export async function POST(request) {
  try {
    const credentials = await request.json();
    if (typeof credentials.email !== 'string' || typeof credentials.password !== 'string' || !credentials.email.trim() || !credentials.password) {
      return NextResponse.json({ error: 'Enter your Bearilly account email and password.' }, { status: 400 });
    }
    if (!BEARILLY_URL || !BEARILLY_API_KEY) return NextResponse.json({ error: 'Bearilly server configuration is missing' }, { status: 500 });
    let bearillyBase;
    try {
      bearillyBase = new URL(BEARILLY_URL);
      const labels = bearillyBase.hostname.split('.');
      if (bearillyBase.hostname.endsWith('.vercel.app') && labels.length >= 4) bearillyBase.hostname = labels.slice(1).join('.');
    } catch {
      console.error('[bearilly-login] BEARILLY_URL must be an absolute URL.');
      return NextResponse.json({ error: 'Server configuration error' }, { status: 500 });
    }
    const bearillyHostname = bearillyBase.hostname;
    if (normalizeHostname(bearillyHostname) === normalizeHostname(new URL(request.url).hostname)) {
      console.error('[bearilly-login] BEARILLY_URL points to this website, not the Bearilly API.');
      return NextResponse.json({ error: 'BEARILLY_URL must use the Bearilly school API URL supplied by Connect, not this website domain' }, { status: 500 });
    }
    const upstream = await fetch(new URL('/api/v1/integration/session', bearillyBase), { method: 'POST', headers: { 'x-bearilly-key': BEARILLY_API_KEY, 'Content-Type': 'application/json' }, body: JSON.stringify({ email: credentials.email, password: credentials.password }) });
    const result = await upstream.json().catch(() => null);
    if (!upstream.ok || !result?.data?.token || !result.data.school_id) return NextResponse.json({ error: result?.error?.message || 'Email or password is incorrect.' }, { status: upstream.status || 502 });
    const cookieStore = await cookies();
    const options = { httpOnly: true, secure: process.env.NODE_ENV === 'production', sameSite: 'lax', path: '/', maxAge: COOKIE_MAX_AGE };
    cookieStore.set(COOKIE_NAME, result.data.token, options);
    cookieStore.set(SCHOOL_COOKIE_NAME, result.data.school_id, options);
    return NextResponse.json({ ok: true, role: result.data.role });
  } catch (error) {
    console.error('[bearilly-login] Could not authenticate or connect the Bearilly session:', error);
    return NextResponse.json({ error: 'Could not sign in to Bearilly. Please try again.' }, { status: 502 });
  }
}

export async function DELETE() {
  const cookieStore = await cookies();
  cookieStore.delete(COOKIE_NAME);
  cookieStore.delete(SCHOOL_COOKIE_NAME);
  return NextResponse.json({ ok: true });
}
